    const uint64_t scaled_descriptor_1 =
        tcgen05_upper_descriptor(scaled_buffer + 32 * N);
    const uint64_t scaled_b_descriptor_0 =
        tcgen05_upper_descriptor(scaled_buffer + (stop / 8) * N);
    const uint64_t scaled_b_descriptor_1 =
        tcgen05_upper_descriptor(
            scaled_buffer + 32 * N + (stop / 8) * N
        );
    const uint32_t instruction_descriptor =
        (1u << 4) | (2u << 7) | (2u << 10)
        | ((trailing / 8) << 17) | (8u << 24);

    if (tid == 0) {
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_0, high_b_descriptor_0,
            instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_1,
            high_b_descriptor_1,
            instruction_descriptor, true
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + 128, scaled_descriptor_0,
            scaled_b_descriptor_0, instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + 128, scaled_descriptor_1,
            scaled_b_descriptor_1, instruction_descriptor, true
        );
        cuda::ptx::tcgen05_commit(
            cuda::ptx::cta_group_1, mma_barrier
        );
    }
    while (!cuda::ptx::mbarrier_try_wait_parity(
        mma_barrier, static_cast<uint32_t>(panel / 16 & 1)
    )) {}
    cuda::ptx::tcgen05_fence_after_thread_sync();

    const int row_group = warp & 3;
    const int column_group = warp / 4;
    const int row = row_group * 32 + lane;
    #pragma unroll
    for (int half = 0; half < 2; ++half) {
        const int first_column = column_group * 16 + half * 64;
        if (first_column < trailing
            && row_group * 32 + 31 >= stop + first_column) {
            const uint32_t address = tmem_base
                + ((row_group * 32) << 16) + first_column;
            uint32_t high_product[16];
            uint32_t scaled_product[16];
            cuda::ptx::tcgen05_ld_32x32b(high_product, address);
            cuda::ptx::tcgen05_ld_32x32b(
                scaled_product, address + 128
            );
            cuda::ptx::tcgen05_wait_ld();
            #pragma unroll
            for (int element = 0; element < 16; ++element) {
                const int column = stop + first_column + element;
                if (row >= column) {
                    const float high =
                        __uint_as_float(high_product[element]);
                    const float scaled =
                        __uint_as_float(scaled_product[element]);
                    const float correction =
                        (scaled - high) * INVERSE_RESIDUAL_SCALE;
                    tile[row * N + column] -= high + correction;
                }
            }
            if (first_column == 0 && warp == stop / 32) {
                factor_panel_16_warp(tile, stop, stop & 31);
            }
        }
    }
    __syncthreads();
}

__device__ __forceinline__ void compensated_rankk_16_tcgen05_m64(
    float* tile,
    uint32_t tmem_base,
    uint64_t* mma_barrier,
    int panel
) {
    constexpr int N = 128;
    constexpr float RESIDUAL_SCALE = 32.0f;
    constexpr float INVERSE_RESIDUAL_SCALE = 1.0f / RESIDUAL_SCALE;
    const int tid = threadIdx.x;
    const int warp = threadIdx.x / 32;
    const int lane = threadIdx.x % 32;
    const int stop = panel + 16;
    const int trailing = N - stop;
    float* scaled_buffer = tile + 64;
    float* high_buffer = tile + 96;

    for (int logical = tid; logical < trailing * 16;
         logical += blockDim.x) {
        const int vector = logical / 16;
        const int k = logical % 16;
        const int row = stop + vector;
        const int physical = (k / 4) * 8 * N
            + (vector / 8) * N
            + (vector & 7) * 4 + (k & 3);
        const float original = tile[row * N + panel + k];
        const float high = wmma::__float_to_tf32(original);
        high_buffer[physical] = high;
        scaled_buffer[physical] = wmma::__float_to_tf32(
            fmaf(RESIDUAL_SCALE, original - high, high)
        );
    }
    asm volatile("fence.proxy.async.shared::cta;" : : : "memory");
    __syncthreads();

    const uint64_t high_descriptor_0 =
        tcgen05_upper_descriptor_m64(high_buffer);
    const uint64_t high_descriptor_1 =
        tcgen05_upper_descriptor_m64(high_buffer + 16 * N);
    const uint64_t scaled_descriptor_0 =
        tcgen05_upper_descriptor_m64(scaled_buffer);
    const uint64_t scaled_descriptor_1 =
        tcgen05_upper_descriptor_m64(scaled_buffer + 16 * N);
    const uint32_t instruction_descriptor =
        (1u << 4) | (2u << 7) | (2u << 10)
        | ((trailing / 8) << 17) | (4u << 24);

    if (tid == 0) {
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_0, high_descriptor_0,
            instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base, high_descriptor_1, high_descriptor_1,
            instruction_descriptor, true
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + (16u << 16), scaled_descriptor_0,
            scaled_descriptor_0, instruction_descriptor, false
        );
        cuda::ptx::tcgen05_mma(
            cuda::ptx::kind_tf32, cuda::ptx::cta_group_1,
            tmem_base + (16u << 16), scaled_descriptor_1,
            scaled_descriptor_1, instruction_descriptor, true
        );
        cuda::ptx::tcgen05_commit(
            cuda::ptx::cta_group_1, mma_barrier
        );
    }
    while (!cuda::ptx::mbarrier_try_wait_parity(
        mma_barrier, static_cast<uint32_t>(panel / 16 & 1)
    )) {}
    cuda::ptx::tcgen05_fence_after_thread_sync();

    const int row_group = warp & 3;
    const int first_column = (warp / 4) * 16;
    if (first_column < trailing
        && row_group * 16 + 15 >= first_column) {
        const uint32_t address = tmem_base
            + ((row_group * 32) << 16) + first_column;
        uint32_t high_product[8];
        uint32_t scaled_product[8];
        cuda::ptx::tcgen05_ld_16x32bx2(
            high_product, address, cuda::ptx::n32_t<8>{}
        );
        cuda::ptx::tcgen05_ld_16x32bx2(
            scaled_product,
            address + (16u << 16),
            cuda::ptx::n32_t<8>{}
        );
        cuda::ptx::tcgen05_wait_ld();
        const int row = stop + row_group * 16 + (lane & 15);
        #pragma unroll
        for (int element = 0; element < 8; ++element) {
            const int column = stop + first_column
                + (lane / 16) * 8 + element;
            if (row < N && row >= column) {
                const float high =
                    __uint_as_float(high_product[element]);
                const float scaled =
                    __uint_as_float(scaled_product[element]);
                const float correction =
                    (scaled - high) * INVERSE_RESIDUAL_SCALE;
                tile[row * N + column] -= high + correction;
            }
        }
        if (first_column == 0 && warp == 0) {
            factor_panel_16_warp(tile, stop);
        }
    }
    __syncthreads();
}

