    if (tid < 32) {
        cuda::ptx::tcgen05_relinquish_alloc_permit(
            cuda::ptx::cta_group_1
        );
        cuda::ptx::tcgen05_dealloc(
            cuda::ptx::cta_group_1, tmem_base, 256
        );
    }

    for (int vector = tid; vector < N * N / 4;
         vector += blockDim.x) {
        const int row = vector / (N / 4);
        const int col = vector % (N / 4) * 4;
        float4 values = reinterpret_cast<const float4*>(tile)[vector];
        if (row < col + 3) values.w = 0.0f;
        if (row < col + 2) values.z = 0.0f;
        if (row < col + 1) values.y = 0.0f;
        if (row < col) values.x = 0.0f;
        reinterpret_cast<float4*>(dst)[vector] = values;
    }
}

